fun play(ids: List<String>, interrupt: Boolean = false): Boolean {
    val clips = ArrayList<ByteArray>()
    for (id in ids) {
        clips.add(AudioPack.bytesFor(context.applicationContext, "$id.mp3") ?: return false)
    }
    // A new bid must be heard NOW, not after the previous call has finished: stale calls are dropped
    // so the voice never trails behind the price on screen.
    if (interrupt) stop()
    clips.forEach { queue.addLast(it) }

private var busy = false

/** True while a call is playing or waiting to play; the auction hall waits for it to end before timing the next step. */
val isSpeaking: Boolean get() = busy || queue.isNotEmpty()

val call: (List<String>, String) -> Unit = { clips, fallback -> if (!voice.play(clips)) speak(fallback) }
// A bid call cuts off whatever the auctioneer was still saying, so the spoken price always matches the screen.
val callNow: (List<String>, String) -> Unit = { clips, fallback -> if (!voice.play(clips, interrupt = true)) speak(fallback) }

// The pause starts only once the auctioneer has finished speaking, so the call is never still
// being said while the next bid arrives (safety cap 8 s in case a clip stalls).
var waited = 0L
while (voice.isSpeaking && waited < 8000L) {
    delay(100L)
    waited += 100L
}
